js=r'''
const data=JSON.parse(document.getElementById('profile-data').textContent);const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];
$('.menu-toggle')?.addEventListener('click',e=>{let open=$('.navlinks').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open)});$$('.navlinks a').forEach(a=>a.addEventListener('click',()=>{$('.navlinks').classList.remove('open');$('.menu-toggle')?.setAttribute('aria-expanded','false')}));
$$('.tabs button').forEach(b=>b.addEventListener('click',()=>{const card=b.closest('.project'),p=data.projects.find(p=>p.slug===card.dataset.slug);$$('.tabs button',card).forEach(x=>x.setAttribute('aria-pressed',x===b));$('.note',card).textContent=[p.ownership,p.challenge,p.outcome][+b.dataset.index]}));
const oldRoute=location.hash.match(/^#\/projects\/([a-z0-9-]+)/);if(oldRoute&&data.projects.some(p=>p.slug===oldRoute[1]))location.replace('project-'+oldRoute[1]+'.html');
const reduced=matchMedia('(prefers-reduced-motion: reduce)');if(!reduced.matches){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.08});$$('.reveal').forEach(e=>io.observe(e));const scene=$('.stage');scene?.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;const r=scene.getBoundingClientRect();scene.style.setProperty('--mx',((e.clientX-r.left)/r.width-.5)*10+'deg');scene.style.setProperty('--my',-((e.clientY-r.top)/r.height-.5)*8+'deg')});scene?.addEventListener('pointerleave',()=>{scene.style.setProperty('--mx','0deg');scene.style.setProperty('--my','0deg')});}
const sections=$$('main>section[id]');if(sections.length){const navio=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)$$('.navlinks a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}),{rootMargin:'-15% 0px -65% 0px'});sections.forEach(s=>navio.observe(s));}
const panel=$('#career-chat'),toggle=$('.chat-toggle'),log=$('.chat-log');function closeChat(){panel.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.focus()}toggle.addEventListener('click',()=>{panel.hidden=!panel.hidden;toggle.setAttribute('aria-expanded',!panel.hidden);if(!panel.hidden)$('input',panel).focus()});$('.chat-close').addEventListener('click',closeChat);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden)closeChat()});
function answer(q){const text=q.toLowerCase();const project=data.projects.find(p=>text.includes(p.title.toLowerCase())||text.includes(p.slug));if(project)return {text:project.ownership+'\n\n'+project.outcome,href:'project-'+project.slug+'.html',label:'Read '+project.title+' case study'};if(/work now|current|tara|employ|job|experience|career|شغل|شغال/.test(text)){let all=/all|previous|history|experience|career/.test(text);return{text:(all?data.experience:data.experience.slice(0,1)).map(x=>x.role+' at '+x.company+' ('+x.period+').').join('\n\n'),href:'index.html#experience',label:'Go to experience'}}if(/skill|stack|flutter|dart|architect|مهار/.test(text))return{text:data.expertise.map(x=>x.name+': '+x.technologies.join(', ')).join('\n\n'),href:'index.html#expertise',label:'Explore expertise'};if(/project|built|app|مشروع/.test(text))return{text:data.projects.map(p=>p.title+': '+p.description+' ('+p.status+').').join('\n\n'),href:'index.html#projects',label:'Explore selected work'};if(/education|university|degree|iti|تعليم/.test(text))return{text:data.education.map(x=>x.degree+' at '+x.school+' ('+x.period+').').join('\n\n'),href:'index.html#education',label:'Go to education'};if(/contact|email|linkedin|reach|تواصل/.test(text))return{text:'Email: '+data.email+'\nLinkedIn: '+data.linkedin,href:'index.html#contact',label:'Contact Mahmoud'};if(/location|where.*live|based|cairo|egypt|مكان/.test(text))return{text:'Mahmoud is based in '+data.location+'.',href:'index.html#contact',label:'Contact details'};if(/resume|cv/.test(text))return{text:'You can download Mahmoud\'s resume here.',href:'Mahmoud-Shady-Resume.pdf',label:'Download resume'};if(/about|who|introduce|مين/.test(text))return{text:data.about.split('\n\n')[0],href:'index.html#about',label:'Read about Mahmoud'};return{text:'I only answer from Mahmoud\'s portfolio facts. I don\'t have verified information about that. Try his projects, current role, skills, education or contact details.'}}
function ask(q){q=q.trim().slice(0,500);if(!q)return;let user=document.createElement('p');user.className='user';user.textContent=q;log.append(user);const a=answer(q),p=document.createElement('p');p.textContent=a.text;log.append(p);if(a.href){const link=document.createElement('a');link.href=a.href;link.textContent=a.label+' ↗';log.append(link)}log.scrollTop=log.scrollHeight;}
$('.chat form').addEventListener('submit',e=>{e.preventDefault();const input=$('input',e.currentTarget);ask(input.value);input.value=''});$$('.chips button').forEach(b=>b.addEventListener('click',()=>ask(b.textContent)));
'''
# Fix small-text contrast and preserve accessible names on compact controls.
css+='\n.label,.label b{color:#496637}.section-top .aside{color:#4d6245}.project-meta,.job .period{color:#4d6542}.case-hero .pills span{border-color:#759363}.case-hero .label{color:#c3dca9}\n'
(out/'site.css').write_text(css)
(out/'site.js').write_text(js)
shutil.copy(root/'assets/fonts/SpaceGrotesk.ttf',out/'SpaceGrotesk.ttf')
