def head(title,desc,canonical):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#102a27"><title>{e(title)}</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{e(canonical)}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{e(canonical)}"><meta property="og:image" content="{e(p['canonical'])}social-preview.png"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Crect rx='22' width='100' height='100' fill='%23102a27'/%3E%3Ctext x='17' y='70' font-family='sans-serif' font-size='55' fill='%23d5f78b'%3EMS%3C/text%3E%3C/svg%3E"><link rel="stylesheet" href="site.css"><script src="site.js" defer></script></head><body><a href="#main" class="skip">Skip to content</a>'''

def nav():
 return '''<header class="nav"><div class="wrap"><a class="brand" href="index.html" aria-label="mahmoudshady. home">mahmoud<span>shady.</span></a><nav class="navlinks" aria-label="Main navigation"><a href="index.html#about">About</a><a href="index.html#projects">Work</a><a href="index.html#experience">Experience</a><a href="index.html#expertise">Expertise</a></nav><a class="navcontact" href="index.html#contact">Let's talk <span aria-hidden="true">↗</span></a><button class="menu-toggle" aria-expanded="false" aria-label="Menu, toggle navigation">Menu ☰</button></div></header>'''

def chat():
 return '''<button class="chat-toggle" aria-controls="career-chat" aria-expanded="false"><span aria-hidden="true">✳</span><span class="toggle-label">Ask about my career</span><span class="sr-only" hidden>Ask about my career</span></button><aside class="chat" id="career-chat" aria-label="Career assistant" hidden><div class="chat-head"><div><strong>Ask about Mahmoud</strong><small>Portfolio facts only. No external AI.</small></div><button class="chat-close" aria-label="Close career assistant">×</button></div><div class="chat-log" role="log" aria-live="polite"><p>Hi. Explore my work, engineering experience, or the details behind a project. What would you like to know?</p></div><div class="chips"><button>Where does he work now?</button><button>Tell me about Hayah</button><button>What are his skills?</button></div><form aria-label="Ask a career question"><input aria-label="Your question" placeholder="Ask a question…" maxlength="500" autocomplete="off"><button aria-label="Send question">↑</button></form></aside>'''

def footer():
 return f'''<footer class="contact" id="contact"><div class="wrap"><div class="label smallcaps">06 / Start a conversation</div><h2>Good products start<br>with <span>good engineering.</span></h2><a class="email" href="mailto:{e(p['email'])}">{e(p['email'])} ↗</a><div class="contact-bottom"><span>Mahmoud Shady / {e(p['location'])}</span><div class="socials"><a href="{e(p['linkedin'])}" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a><a href="{e(p['github'])}" target="_blank" rel="noopener noreferrer">GitHub ↗</a><a href="Mahmoud-Shady-Resume.pdf" download>Resume ↓</a><a href="#main">Back to top ↑</a></div></div></div></footer>'''

def end():
 return chat()+'<script type="application/json" id="profile-data">'+json.dumps(p,ensure_ascii=False).replace('</','<\\/')+'</script></body></html>'

def pills(items): return '<div class="pills">'+''.join('<span>'+e(x)+'</span>' for x in items)+'</div>'
def sectiontop(num,label,title,aside=''):
 return f'<div class="section-top"><div><div class="label smallcaps"><b>{num}</b>{e(label)}</div><h2>{title}</h2></div><p class="aside">{e(aside)}</p></div>'

tones=['#d8e5be','#e6d5b0','#e7cdd7','#cbdaca','#c9d9e3','#e3dcc0','#d6d9c5']
cards=''
for i,project in enumerate(p['projects']):
 x=project
 cards+=f'''<article class="project reveal" data-slug="{e(x['slug'])}"><div class="art" style="--tone:{tones[i]}" aria-hidden="true"><span class="art-no">{e(x['number'])} / MOBILE ENGINEERING</span><span class="art-word">{e(x['title'])}</span><div class="mini-ui"><i></i><i></i><i></i><i></i></div><span class="art-category">{e(x['category'])}</span></div><div class="project-body"><div class="project-meta">{e(x['status'])}</div><h3>{e(x['title'])}</h3><p class="project-desc">{e(x['description'])}</p>{pills(x['techStack'])}<div class="notes"><div class="tabs" role="group" aria-label="{e(x['title'])} project notes">{''.join(f'<button data-index="{j}" aria-pressed="{str(j==0).lower()}">{label}</button>' for j,label in enumerate(['My work','The challenge','Current status']))}</div><p class="note" aria-live="polite">{e(x['ownership'])}</p></div><div class="project-footer"><span>Project {i+1:02} / 07</span><a href="project-{e(x['slug'])}.html">View case study ↗</a></div></div></article>'''

jobs=''
for x in p['experience']:
 jobs+=f'''<article class="job reveal"><div><h3>{e(x['role'])}</h3><div class="company">{e(x['company'])}</div><div class="period">{e(x['period'])}</div></div><ul>{''.join('<li>'+e(s.strip().lstrip('•').strip())+'</li>' for s in x['description'].splitlines() if s.strip())}</ul></article>'''
expertise=''.join(f'<article class="expertise reveal"><span class="icon" aria-hidden="true">{icon}</span><h3>{e(x["name"])}</h3><p>{e(x["description"])}</p>{pills(x["technologies"])}</article>' for icon,x in zip(['⌘','◈','↗','⊞','✳','✓'],p['expertise']))
edu=''.join(f'<article class="edu reveal"><span class="smallcaps label">{e(x["period"])}</span><h3>{e(x["school"])}</h3><p>{e(x["degree"])}</p></article>' for x in p['education'])
about=p['about'].split('\n\n')
main=head('Mahmoud Shady | Software & Mobile Engineer','Complete mobile applications. Considered engineering. Explore Mahmoud Shady’s mobile products, architecture, experience, and project case studies.',p['canonical'])+nav()+f'''
<main id="main"><section class="hero" aria-label="Introduction"><div class="wrap"><div class="hero-inner"><div><div class="eyebrow smallcaps"><i class="dot"></i> Software engineer / Mobile specialist</div><h1>Complete apps.<br><em>Considered</em><br>engineering.</h1><p class="hero-desc">I'm Mahmoud Shady. I turn business requirements into complete mobile applications, from architecture to delivery and everything that follows.</p><div class="buttons"><a class="btn primary" href="#projects">Explore selected work <span>↘</span></a><a class="btn" href="Mahmoud-Shady-Resume.pdf" download>Download resume <span>↓</span></a></div><div class="hero-meta smallcaps">Cairo, Egypt &nbsp; / &nbsp; Flutter & Dart · iOS + Android</div></div><div class="stage" aria-label="Animated conceptual mobile engineering illustration"><div class="scene"><div class="orbit"></div><div class="orbit second"></div><div class="phone" aria-hidden="true"><div class="screen"><div class="screenhead"><span>9:41</span><span>● ▰</span></div><h3>Built for<br>the everyday.</h3><div class="app-visual"><b>✳</b></div><div class="screenrow"><span>A considered experience</span><span>↗</span></div><div class="screenrow"><span>From idea to interaction</span><span>↗</span></div><div class="screenrow"><span>Made to keep working</span><span>✓</span></div><div class="screenbar"></div></div></div><div class="float code" aria-hidden="true"><div class="lights">● ● ●</div><div>class <i>MobileExperience</i> {{</div><div>&nbsp; architecture: <i>clean</i>,</div><div>&nbsp; interaction: <i>considered</i>,</div><div>&nbsp; platform: <i>[iOS, Android]</i></div><div>}}</div></div><div class="float ship" aria-hidden="true"><span class="mark">✓</span><strong>Beyond the interface.</strong><p>Architecture → Integration → Delivery</p></div><div class="composition-label smallcaps">Conceptual engineering illustration</div></div></div></div><div class="hero-bottom smallcaps"><span>01 / Built with intention</span><span>Clean Architecture</span><span>BLoC / Cubit</span><span>REST APIs & Firebase</span><span class="last">Responsive & RTL</span></div></div></section>
<section class="section" id="about"><div class="wrap">{sectiontop('01','The engineer behind the work','The whole product.<br>Not just the screen.')}<div class="about-grid"><div><div class="about-big">I build the connections between an idea and an application people can actually use.</div><div class="stats"><div class="stat"><strong>07</strong><span>Selected projects</span></div><div class="stat"><strong>iOS</strong><span>+ Android development</span></div><div class="stat"><strong>End-to-end</strong><span>Mobile responsibility</span></div></div></div><div class="about-copy"><p>{e(about[0])}</p><p>{e(about[1])}</p><details><summary>More about my approach ↗</summary>{''.join('<p>'+e(x)+'</p>' for x in about[2:])}</details></div></div></div></section>
<section class="section work" id="projects"><div class="wrap">{sectiontop('02','Selected work','Different products.<br>One engineering mindset.','A closer look at the mobile products I have built and maintained. Explore the work, the challenge, and where each project stands.')}<div class="projects">{cards}</div></div></section>
<section class="section" id="experience"><div class="wrap">{sectiontop('03','Experience','Ownership, in practice.','Professional roles and project-based work. Dates are shown as recorded; some engagements overlap.')}<div class="timeline">{jobs}</div></div></section>
<section class="section" id="expertise"><div class="wrap">{sectiontop('04','Engineering toolkit','Built on clear foundations.','The tools matter. How they work together matters more.')}<div class="expertise-grid">{expertise}</div></div></section>
<section class="section" id="education"><div class="wrap">{sectiontop('05','Education','Where the foundations began.')}<div class="education-grid">{edu}</div></div></section></main>'''+footer()+end()
# Keep headings original and clear, without a negative slogan.
