# Give the mobile icon button a stable accessible name.
main=main.replace('class="chat-toggle"','class="chat-toggle" aria-label="Ask about my career"')
(out/'index.html').write_text(main)
for x in p['projects']:
 body=head(x['title']+' | Mahmoud Shady',x['description'],p['canonical']+'project-'+x['slug']+'.html')+nav()+f'''<main id="main"><header class="case-hero"><div class="wrap"><a href="index.html#projects" class="smallcaps">← All selected work</a><div class="smallcaps" style="margin-top:45px;color:#c1dcaa">{e(x['category'])} / {e(x['status'])}</div><h1>{e(x['title'])}</h1><p class="heading">{e(x['heading'])}</p>{pills(x['techStack'])}</div></header><div class="wrap"><article class="case-content"><section><div class="label smallcaps">01 / My responsibility</div><h2>My work on {e(x['title'])}</h2><p>{e(x['ownership'])}</p></section><section><div class="label smallcaps">02 / The challenge</div><h2>The engineering problem</h2><p>{e(x['challenge'])}</p></section>'''
 if x['features']:body+='<section><div class="label smallcaps">03 / Implementation</div><h2>Behind the experience</h2><ul>'+''.join('<li>'+e(z)+'</li>' for z in x['features'])+'</ul></section>'
 body+=f'<section><div class="label smallcaps">04 / Current status</div><h2>Where the project stands</h2><p>{e(x["outcome"])}</p></section><div class="buttons"><a class="btn primary" href="index.html#projects">← Back to selected work</a>'
 for k,label in [('playStoreUrl','Google Play'),('appStoreUrl','App Store')]:
  if x.get(k):body+=f'<a class="btn" href="{e(x[k])}" target="_blank" rel="noopener noreferrer">{label} ↗</a>'
 body+='</div></article></div></main>'+footer()+end()
 body=body.replace('class="chat-toggle"','class="chat-toggle" aria-label="Ask about my career"')
 (out/('project-'+x['slug']+'.html')).write_text(body)
 # Preserve prior crawlable case-study URLs and Flutter fragment entry points.
 legacy=out/'case-studies'/x['slug'];legacy.mkdir(parents=True,exist_ok=True)
 (legacy/'index.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta http-equiv="refresh" content="0;url=../../project-'+x['slug']+'.html"><title>'+e(x['title'])+'</title><link rel="canonical" href="'+p['canonical']+'project-'+x['slug']+'.html"></head><body><a href="../../project-'+x['slug']+'.html">Read '+e(x['title'])+' case study</a></body></html>')
(out/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+p['canonical']+'sitemap.xml\n')
(out/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+p['canonical']+x+'</loc></url>' for x in ['']+['project-'+x['slug']+'.html' for x in p['projects']])+'</urlset>')
(out/'.nojekyll').touch()
# Machine-readable identity facts drawn only from the same data.
schema={'@context':'https://schema.org','@type':'Person','name':p['name'],'jobTitle':p['role'],'url':p['canonical'],'sameAs':[p['linkedin'],p['github']],'email':p['email']}
index=out/'index.html';index.write_text(index.read_text().replace('</head>','<script type="application/ld+json">'+json.dumps(schema)+'</script></head>'))
